selector_to_html = {"a[href=\"#id5\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u72b6\u6001<a class=\"headerlink\" href=\"#id5\" title=\"Link to this heading\">#</a></h2><p>FlagPrism \u901a\u8fc7 FlagTree \u5b50\u6a21\u5757\u4ea4\u4ed8\uff0c\u968f FlagTree wheel \u4e00\u8d77\u5b89\u88c5\u3002</p>", "a[href=\"#id3\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u540e\u7aef\u652f\u6301<a class=\"headerlink\" href=\"#id3\" title=\"Link to this heading\">#</a></h2><p>\u4e0b\u8868\u5c55\u793a FlagPrism \u7684\u652f\u6301\u8def\u7ebf\u56fe\uff0c\u63cf\u8ff0\u7684\u662f Debugger \u4e0e Profiler \u7684\u96c6\u6210\u72b6\u6001\uff0c\u800c\u4e0d\u662f\u76f8\u5e94 FlagTree \u7f16\u8bd1\u5668\u540e\u7aef\u7684\u53ef\u7528\u72b6\u6001\u3002</p>", "a[href=\"#id4\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u6784\u5efa\u6a21\u5f0f<a class=\"headerlink\" href=\"#id4\" title=\"Link to this heading\">#</a></h2><p>Python wheel \u4ec5\u652f\u6301\u4e24\u79cd\u6784\u5efa\u6a21\u5f0f\uff1a</p>", "a[href=\"#flagtree\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u4e0e FlagTree \u7684\u5173\u7cfb<a class=\"headerlink\" href=\"#flagtree\" title=\"Link to this heading\">#</a></h2><p>FlagTree \u662f\u9762\u5411 AI \u52a0\u901f\u5668\u7684\u7edf\u4e00\u591a\u540e\u7aef\u7f16\u8bd1\u5668\uff0c\u4f7f Triton \u7a0b\u5e8f\u80fd\u591f\u5728\u4e0d\u540c\u7c7b\u578b\u7684 AI \u52a0\u901f\u8bbe\u5907\u4e0a\u8fd0\u884c\u3002FlagPrism \u4e3a FlagTree \u63d0\u4f9b\u914d\u5957\u7684\u89c2\u6d4b\u5de5\u5177\uff0c\u5e2e\u52a9\u5f00\u53d1\u8005\u8c03\u8bd5 kernel \u6b63\u786e\u6027\u3001\u5206\u6790\u8fd0\u884c\u884c\u4e3a\u3001\u5b9a\u4f4d\u6027\u80fd\u74f6\u9888\u5e76\u4f18\u5316 Triton workload\u3002</p><p>FlagTree \u5c06 FlagPrism \u4f5c\u4e3a <code class=\"docutils literal notranslate\"><span class=\"pre\">third_party/FlagPrism</span></code> \u5b50\u6a21\u5757\u6d88\u8d39\uff0c\u4e0d\u518d\u5355\u72ec\u53d1\u5e03 <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-debugger</span></code> \u4e0e <code class=\"docutils literal notranslate\"><span class=\"pre\">flagtree-profiler</span></code> wheel\u3002\u5728 FlagTree \u4ed3\u5e93\u8fd0\u884c <code class=\"docutils literal notranslate\"><span class=\"pre\">pip</span> <span class=\"pre\">wheel</span> <span class=\"pre\">.</span></code> \u4f1a\u5728\u540c\u4e00\u4e2a CMake graph \u4e2d\u6784\u5efa core\u3001Debugger \u548c Profiler\uff0c\u5e76\u6253\u5305\u8fdb\u5355\u4e2a FlagTree wheel\uff1a</p>", "a[href=\"#id1\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">\u6982\u89c8<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h1><p>FlagPrism \u662f\u9762\u5411 Triton \u7a0b\u5e8f\u7684\u591a\u540e\u7aef\u8c03\u8bd5\u4e0e\u6027\u80fd\u5206\u6790\u5de5\u5177\uff0c\u4e3a NVIDIA GPU \u53ca\u591a\u79cd AI \u52a0\u901f\u8bbe\u5907\u63d0\u4f9b\u4e00\u81f4\u7684\u89c2\u6d4b\u5de5\u4f5c\u6d41\uff1a\u5728\u7f16\u8bd1\u671f\u548c\u8fd0\u884c\u671f\u89c2\u6d4b Triton kernel\uff0c\u5c06\u6e90\u7801\u4e0a\u4e0b\u6587\u3001Triton IR \u64cd\u4f5c\u4e0e\u8bbe\u5907\u4e8b\u4ef6\u5173\u8054\u8d77\u6765\uff0c\u5e76\u628a\u91c7\u96c6\u7684\u6570\u636e\u8f6c\u5316\u4e3a\u62a5\u544a\uff0c\u5e2e\u52a9\u5f00\u53d1\u8005\u5206\u6790\u4e0d\u540c\u52a0\u901f\u5668\u540e\u7aef\u4e0a\u7684\u7a0b\u5e8f\u6b63\u786e\u6027\u3001\u5185\u5b58\u884c\u4e3a\u548c\u6027\u80fd\u8868\u73b0\u3002</p>", "a[href=\"#id2\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">\u7ec4\u4ef6<a class=\"headerlink\" href=\"#id2\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
